import { z } from 'zod/mini';
import { publicErrorSchema } from './result.ts';
export * from './result.ts';
export {
  PUBLIC_ERRORS,
  INTERNAL_ERRORS,
  type PublicErrorCode,
  type InternalErrorCode,
} from './errors.generated.ts';

// HTML maxlength and the native adapter use UTF-16 units; Zod maxLength counts code points.
const noteLength = z.superRefine<string>((text, context) => {
  if (text.length > 1000)
    context.addIssue({ code: 'too_big', origin: 'string', maximum: 1000, inclusive: true });
});

export const noteInput = z.strictObject({
  text: z.string().check(z.trim(), z.minLength(1), noteLength),
});
export const noteSchema = z.strictObject({
  id: z.uuid(),
  text: z.string().check(z.minLength(1), noteLength),
  createdAt: z.int().check(z.gte(0)),
});
export const notesSchema = z.array(noteSchema);
export const apiErrorSchema = z.strictObject({
  error: publicErrorSchema,
  requestId: z.string().check(z.uuid()),
});
export type Note = z.infer<typeof noteSchema>;
export type NoteInput = z.infer<typeof noteInput>;

// Native u32 values must remain exact, nonnegative integers at the renderer boundary.
export const counterValueSchema = z.int().check(z.gte(0), z.lte(4_294_967_295));

import {
  ROOT_CONTEXT,
  SpanKind,
  SpanStatusCode,
  TraceFlags,
  trace,
  type SpanContext,
} from '@opentelemetry/api';
import {
  BasicTracerProvider,
  InMemorySpanExporter,
  SimpleSpanProcessor,
  type ReadableSpan,
} from '@opentelemetry/sdk-trace-base';
import { resourceFromAttributes } from '@opentelemetry/resources';
import {
  capture,
  captureSync,
  Err,
  Ok,
  failure,
  publicFailure,
  PUBLIC_ERRORS,
  INTERNAL_ERRORS,
  decodePublicError,
  type Result,
  type AppError,
  type PublicError,
} from '@lantern-lab/contracts';

export const OPERATIONS = [
  'notes.list',
  'notes.add',
  'notes.remove',
  'notes.export',
  'http.request',
  'binding.kv.read',
  'binding.kv.write',
  'binding.r2.read',
  'binding.r2.write',
  'binding.d1.read',
  'binding.d1.write',
  'ui.initialize',
  'counter.read',
  'counter.increment',
  'counter.reset',
] as const;
export type OperationName = (typeof OPERATIONS)[number];
export type TelemetryConfig = {
  service: string;
  instance: string;
  environment?: string;
  version?: string;
  runId?: string;
  endpoint?: string;
  send?: typeof fetch;
};
export type TraceCarrier = { traceparent: string };
const finiteId = /^[a-f0-9]{32}$/u;
const safeResource = /^[a-zA-Z0-9._-]{1,128}$/u;
const nano = (time: [number, number]): string =>
  (BigInt(time[0]) * 1_000_000_000n + BigInt(time[1])).toString();
const attr = (key: string, value: string | number) => ({
  key,
  value: typeof value === 'number' ? { doubleValue: value } : { stringValue: value },
});

export function parseTraceparent(value: string | null | undefined): SpanContext | undefined {
  const match = /^00-([a-f0-9]{32})-([a-f0-9]{16})-([a-f0-9]{2})$/u.exec(value ?? '');
  if (!match || /^0+$/u.test(match[1]!) || /^0+$/u.test(match[2]!)) return;
  return {
    traceId: match[1]!,
    spanId: match[2]!,
    traceFlags: Number.parseInt(match[3]!, 16) & TraceFlags.SAMPLED,
    isRemote: true,
  };
}
export function collectorEndpoint(value: string): Result<string> {
  const parsed = captureUrl(value);
  if (!parsed.ok) return parsed;
  const url = parsed.value;
  if (
    url.username ||
    url.password ||
    url.search ||
    url.hash ||
    !['http:', 'https:'].includes(url.protocol) ||
    (url.protocol === 'http:' && !['localhost', '127.0.0.1', '[::1]'].includes(url.hostname))
  )
    return Err(failure('input_invalid'));
  return Ok(url.href.replace(/\/$/u, ''));
}
const captureUrl = (value: string): Result<URL> =>
  captureSync(() => new URL(value), 'input_invalid');

export function createTelemetry(config: TelemetryConfig) {
  for (const field of [
    config.service,
    config.instance,
    config.environment ?? 'local',
    config.version ?? 'development',
    config.runId ?? 'local',
  ])
    if (!safeResource.test(field)) throw new Error('Invalid finite telemetry resource');
  const selected = config.endpoint ? collectorEndpoint(config.endpoint) : undefined;
  if (selected && !selected.ok)
    throw new Error(
      'Invalid collector endpoint; use loopback HTTP or verified HTTPS without credentials/query',
    );
  const endpoint = selected?.ok ? selected.value : undefined;
  const resource = {
    'service.name': config.service,
    'service.instance.id': config.instance,
    'service.version': config.version ?? 'development',
    'deployment.environment.name': config.environment ?? 'local',
    'test.run.id': config.runId ?? 'local',
  };
  const exporter = new InMemorySpanExporter();
  const provider = new BasicTracerProvider({
    resource: resourceFromAttributes(resource),
    spanProcessors: [new SimpleSpanProcessor(exporter)],
  });
  const tracer = provider.getTracer('application-boundary', '1.0.0');
  const resources = {
    attributes: Object.entries(resource).map(([key, value]) => attr(key, value)),
  };
  let lastExport: Result<void> = Ok(undefined);
  let dropped = 0;
  const pending: {
    span?: ReadableSpan;
    attributes: ReturnType<typeof attr>[];
    traceId: string;
    spanId: string;
    start: string;
    end: string;
    duration: number;
    failed: boolean;
    cancelled: boolean;
  }[] = [];
  let draining: Promise<Result<void>> | undefined;
  function start(operation: OperationName, carrier?: TraceCarrier, requestId?: string) {
    if (!(OPERATIONS as readonly string[]).includes(operation))
      throw new Error('Unknown finite operation');
    const parent = parseTraceparent(carrier?.traceparent);
    const context = parent ? trace.setSpanContext(ROOT_CONTEXT, parent) : ROOT_CONTEXT;
    const span = tracer.startSpan(
      operation,
      {
        kind: operation === 'http.request' ? SpanKind.SERVER : SpanKind.INTERNAL,
        attributes: { 'operation.name': operation },
      },
      context,
    );
    const started = performance.now();
    const id = span.spanContext();
    const traceparent = `00-${id.traceId}-${id.spanId}-${(id.traceFlags & TraceFlags.SAMPLED).toString(16).padStart(2, '0')}`;
    let finished = false;
    return {
      traceparent,
      traceId: id.traceId,
      spanId: id.spanId,
      finish(result: Result<unknown, AppError | PublicError>): void {
        if (finished) throw new Error('An operation may finish only once');
        finished = true;
        const attributes = [attr('operation.name', operation)];
        if (requestId && finiteId.test(requestId.replaceAll('-', '')))
          attributes.push(attr('app.request.id', requestId));
        let cancelled = false;
        if (!result.ok) {
          const internal = 'internalCode' in result.error ? result.error : undefined;
          const validInternal =
            internal &&
            Object.hasOwn(INTERNAL_ERRORS, internal.internalCode) &&
            finiteId.test(internal.diagnosticId)
              ? internal
              : internal
                ? failure('response_invalid')
                : undefined;
          const decoded = validInternal
            ? Ok(publicFailure(validInternal))
            : decodePublicError(result.error);
          const problem = decoded.ok ? decoded.value : publicFailure(decoded.error);
          const errorType = validInternal
            ? validInternal.internalCode
            : decoded.ok
              ? problem.code
              : decoded.error.internalCode;
          cancelled = problem.failureClass === 'cancelled';
          attributes.push(
            attr('error.type', errorType),
            attr('app.failure.class', problem.failureClass),
            attr('app.diagnostic.id', problem.diagnosticId),
          );
          span.setStatus({
            code: cancelled ? SpanStatusCode.UNSET : SpanStatusCode.ERROR,
            message: problem.code,
          });
          span.addEvent(
            'operation.failed',
            Object.fromEntries(
              attributes.map((entry) => [
                entry.key,
                'stringValue' in entry.value ? entry.value.stringValue : entry.value.doubleValue,
              ]),
            ),
          );
        }
        for (const entry of attributes)
          if ('stringValue' in entry.value) span.setAttribute(entry.key, entry.value.stringValue);
        span.end();
        if (!(id.traceFlags & TraceFlags.SAMPLED)) return;
        const readable = exporter
          .getFinishedSpans()
          .find((entry) => entry.spanContext().spanId === id.spanId);
        exporter.reset();
        if (endpoint) {
          if (pending.length >= 128) {
            dropped += 1;
            lastExport = Err(failure('network_failed'));
          } else
            pending.push({
              ...(readable ? { span: readable } : {}),
              attributes,
              traceId: id.traceId,
              spanId: id.spanId,
              start: readable
                ? nano(readable.startTime)
                : (BigInt(Date.now()) * 1_000_000n).toString(),
              end: readable ? nano(readable.endTime) : (BigInt(Date.now()) * 1_000_000n).toString(),
              duration: performance.now() - started,
              failed: !result.ok,
              cancelled,
            });
        }
      },
    };
  }
  async function drain(): Promise<Result<void>> {
    if (!endpoint) return Ok(undefined);
    const records = pending.splice(0);
    if (!records.length) return lastExport;
    const spans = records.flatMap((record) =>
      record.span
        ? [
            {
              traceId: record.traceId,
              spanId: record.spanId,
              ...(record.span.parentSpanContext
                ? { parentSpanId: record.span.parentSpanContext.spanId }
                : {}),
              name: record.span.name,
              kind: record.span.kind + 1,
              startTimeUnixNano: record.start,
              endTimeUnixNano: record.end,
              attributes: record.attributes,
              status: { code: record.span.status.code },
              events: record.span.events.map((event) => ({
                name: event.name,
                timeUnixNano: nano(event.time),
                attributes: record.attributes,
              })),
            },
          ]
        : [],
    );
    const bounds = [5, 25, 100, 500, 2000];
    const metrics = records.map((record) => ({
      name: 'application.operation.duration',
      unit: 'ms',
      histogram: {
        aggregationTemporality: 1,
        dataPoints: [
          {
            startTimeUnixNano: record.start,
            timeUnixNano: record.end,
            count: '1',
            sum: record.duration,
            explicitBounds: bounds,
            bucketCounts: bounds
              .map((bound, index) =>
                record.duration <= bound && (index === 0 || record.duration > bounds[index - 1]!)
                  ? '1'
                  : '0',
              )
              .concat([record.duration > bounds.at(-1)! ? '1' : '0']),
            attributes: record.attributes.filter((entry) =>
              ['operation.name', 'app.failure.class'].includes(entry.key),
            ),
            exemplars: [
              {
                timeUnixNano: record.end,
                asDouble: record.duration,
                traceId: record.traceId,
                spanId: record.spanId,
                filteredAttributes: [],
              },
            ],
          },
        ],
      },
    }));
    const logs = records.map((record) => ({
      timeUnixNano: record.end,
      observedTimeUnixNano: record.end,
      traceId: record.traceId,
      spanId: record.spanId,
      severityNumber: record.cancelled || !record.failed ? 9 : 17,
      severityText: record.cancelled || !record.failed ? 'INFO' : 'ERROR',
      body: { stringValue: record.failed ? 'operation.failed' : 'operation.completed' },
      attributes: record.attributes,
    }));
    const scope = { name: 'application-boundary', version: '1.0.0' };
    const payloads = [
      ['traces', { resourceSpans: [{ resource: resources, scopeSpans: [{ scope, spans }] }] }],
      [
        'logs',
        { resourceLogs: [{ resource: resources, scopeLogs: [{ scope, logRecords: logs }] }] },
      ],
      [
        'metrics',
        { resourceMetrics: [{ resource: resources, scopeMetrics: [{ scope, metrics }] }] },
      ],
    ] as const;
    for (const [signal, payload] of payloads) {
      const response = await capture(
        () =>
          (config.send ?? fetch)(`${endpoint}/v1/${signal}`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify(payload),
            signal: AbortSignal.timeout(3000),
          }),
        'network_failed',
      );
      if (!response.ok) {
        dropped += records.length;
        lastExport = response;
        return response;
      }
      const body = await capture(
        () => response.value.json() as Promise<unknown>,
        'response_invalid',
      );
      if (!response.value.ok || !body.ok || rejectsOtlp(body.value)) {
        dropped += records.length;
        lastExport = Err(failure('response_invalid'));
        return lastExport;
      }
    }
    lastExport = Ok(undefined);
    return lastExport;
  }
  function flush(): Promise<Result<void>> {
    if (draining)
      return draining.then((result) => (result.ok && pending.length ? flush() : result));
    draining = drain().finally(() => {
      draining = undefined;
    });
    return draining.then((result) => (result.ok && pending.length ? flush() : result));
  }
  return {
    start,
    flush,
    status: () => ({ enabled: Boolean(endpoint), pending: pending.length, dropped, lastExport }),
    shutdown: () => provider.shutdown(),
  };
}
export type Telemetry = ReturnType<typeof createTelemetry>;

// HTTP/Service Binding adapter: preserve Response streaming and correlate the
// incoming hop. Platform exceptions become the same public failure contract.
export async function observeHttp(
  request: Request,
  config: TelemetryConfig,
  handler: (request: Request) => Promise<Response>,
): Promise<Response> {
  const telemetry = createTelemetry(config);
  const requestId = crypto.randomUUID();
  const operation = telemetry.start(
    'http.request',
    { traceparent: request.headers.get('traceparent') ?? '' },
    requestId,
  );
  const headers = new Headers(request.headers);
  headers.set('traceparent', operation.traceparent);
  const captured = await capture(
    () => handler(new Request(request, { headers })),
    'unexpected_failure',
  );
  const response = captured.ok
    ? captured.value
    : Response.json({ error: publicFailure(captured.error), requestId }, { status: 500 });
  let outcome: Result<unknown, AppError | PublicError> = captured;
  if (captured.ok && response.status >= 400) {
    const publicCode = response.headers.get('x-error-code');
    const policy = Object.entries(PUBLIC_ERRORS).find(
      ([code, value]) => code === publicCode && value.status === response.status,
    );
    const id = response.headers.get('x-diagnostic-id');
    const error = failure('unexpected_failure', id && finiteId.test(id) ? id : undefined);
    outcome = Err(
      policy
        ? {
            code: policy[0] as keyof typeof PUBLIC_ERRORS,
            message: policy[1].message,
            failureClass: policy[1].class,
            retry: policy[1].retry,
            remediation: policy[1].remediation,
            diagnosticId: error.diagnosticId,
          }
        : error,
    );
  }
  operation.finish(outcome);
  const exported = await telemetry.flush();
  await telemetry.shutdown();
  const telemetryState = !telemetry.status().enabled
    ? 'disabled'
    : exported.ok
      ? 'accepted'
      : 'failed';
  // Preserve runtime-owned Response flags (including manually encoded streaming bodies).
  // Immutable platform responses are also preserved: copying can lose opaque
  // runtime encoding flags. Their export state remains available in telemetry.
  const annotated = captureSync(() => {
    response.headers.set('traceparent', operation.traceparent);
    response.headers.set('x-telemetry-state', telemetryState);
    return response;
  }, 'unexpected_failure');
  if (annotated.ok) return annotated.value;
  return response;
}

export async function observeAdapter<T>(
  telemetry: Telemetry,
  name: OperationName,
  action: (carrier: TraceCarrier) => Promise<Result<T, PublicError>>,
): Promise<Result<T, PublicError>> {
  const operation = telemetry.start(name);
  const captured = await capture(
    () => action({ traceparent: operation.traceparent }),
    'unexpected_failure',
  );
  const result = captured.ok ? captured.value : Err(publicFailure(captured.error));
  operation.finish(result);
  const exported = await telemetry.flush();
  if (!exported.ok)
    console.warn(
      JSON.stringify({
        event: 'telemetry.export.failed',
        errorCode: exported.error.internalCode,
        diagnosticId: exported.error.diagnosticId,
      }),
    );
  return result;
}

export function rejectsOtlp(body: unknown): boolean {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return true;
  if (!('partialSuccess' in body)) return false;
  const partial = body.partialSuccess;
  if (!partial || typeof partial !== 'object' || Array.isArray(partial)) return true;
  return Object.entries(partial).some(([key, value]) =>
    key === 'errorMessage'
      ? value !== ''
      : !['rejectedSpans', 'rejectedLogRecords', 'rejectedDataPoints'].includes(key) ||
        ![0, '0'].includes(value),
  );
}

import { createTelemetry, observeAdapter, type TraceCarrier } from '@lantern-lab/observability';
import { invoke } from '@tauri-apps/api/core';
import {
  counterValueSchema,
  noteSchema,
  notesSchema,
  capturePublic,
  decode,
  Err,
  Ok,
  publicFailure,
  type Result,
  type PublicError,
} from '@lantern-lab/contracts';
import type { CounterAdapter } from './counter';
import type { NotesAdapter } from '@lantern-lab/ui';

async function command(
  name: string,
  carrier: TraceCarrier,
  args?: Record<string, unknown>,
): Promise<Result<unknown, PublicError>> {
  return capturePublic(() => invoke<unknown>(name, { ...args, telemetry: carrier }), 'ipc_failed');
}

const telemetry = createTelemetry({
  service: 'desktop-counter-lantern-desktop-renderer',
  instance: 'desktop-counter-lantern',
  runId: import.meta.env.VITE_OTEL_RUN_ID ?? 'local',
  version: import.meta.env.VITE_OTEL_VERSION ?? 'development',
  ...(import.meta.env.VITE_OTEL_ENDPOINT ? { endpoint: import.meta.env.VITE_OTEL_ENDPOINT } : {}),
});

export const nativeNotes: NotesAdapter = {
  async list() {
    return observeAdapter(telemetry, 'notes.list', async (carrier) => {
      const received = await command('list_notes', carrier);
      if (!received.ok) return received;
      const parsed = decode(notesSchema, received.value);
      return parsed.ok ? parsed : Err(publicFailure(parsed.error));
    });
  },
  async add(input) {
    return observeAdapter(telemetry, 'notes.add', async (carrier) => {
      const received = await command('add_note', carrier, { text: input.text });
      if (!received.ok) return received;
      const parsed = decode(noteSchema, received.value);
      return parsed.ok ? parsed : Err(publicFailure(parsed.error));
    });
  },
  async remove(id) {
    return observeAdapter(telemetry, 'notes.remove', async (carrier) => {
      const received = await command('delete_note', carrier, { id });
      return received.ok ? Ok(undefined) : received;
    });
  },
  async export() {
    return observeAdapter(telemetry, 'notes.export', async (carrier) => {
      const received = await command('export_notes', carrier);
      return received.ok ? Ok(undefined) : received;
    });
  },
};

async function counterCommand(
  name: string,
  carrier: TraceCarrier,
): Promise<Result<number, PublicError>> {
  const received = await command(name, carrier);
  if (!received.ok) return received;
  const parsed = decode(counterValueSchema, received.value);
  return parsed.ok ? parsed : Err(publicFailure(parsed.error));
}

export const nativeCounter: CounterAdapter = {
  async read(): Promise<Result<number, PublicError>> {
    return observeAdapter(telemetry, 'counter.read', (carrier) => counterCommand('read_counter', carrier));
  },
  async increment(): Promise<Result<number, PublicError>> {
    return observeAdapter(telemetry, 'counter.increment', (carrier) => counterCommand('increment_counter', carrier));
  },
  async reset(): Promise<Result<number, PublicError>> {
    return observeAdapter(telemetry, 'counter.reset', (carrier) => counterCommand('reset_counter', carrier));
  },
};

import { useCallback, useEffect, useState } from 'react';
import { Ok, launch, type PublicError, type Result } from '@lantern-lab/contracts';

export type CounterAdapter = {
  read(this: void): Promise<Result<number, PublicError>>;
  increment(this: void): Promise<Result<number, PublicError>>;
  reset(this: void): Promise<Result<number, PublicError>>;
};

export function CounterPanel({ adapter }: { adapter: CounterAdapter }) {
  const [value, setValue] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const reportUnexpected = useCallback(() => {
    setError('The counter could not be updated. Read its current value before trying again.');
    setLoading(false);
    setBusy(false);
  }, []);

  useEffect(() => {
    let current = true;
    launch(
      async () => {
        const result = await adapter.read();
        if (!current) return;
        if (result.ok) setValue(result.value);
        else setError(result.error.message);
        setLoading(false);
      },
      () => {
        if (current) reportUnexpected();
      },
    );
    return () => {
      current = false;
    };
  }, [adapter, reportUnexpected]);

  const update = async (
    action: () => Promise<Result<number, PublicError>>,
  ): Promise<Result<void, PublicError>> => {
    setBusy(true);
    setError('');
    const result = await action();
    if (result.ok) setValue(result.value);
    else setError(result.error.message);
    setBusy(false);
    return result.ok ? Ok(undefined) : result;
  };

  const run = (action: () => Promise<Result<number, PublicError>>) => {
    launch(async () => {
      const result = await update(action);
      if (!result.ok) return;
    }, reportUnexpected);
  };

  return (
    <aside aria-label="Counter" className="mx-auto mt-4 max-w-2xl rounded-xl border p-6">
      <h2 className="text-xl font-semibold">Counter</h2>
      <p className="my-2 text-sm">Kept in native memory until the app closes.</p>
      <output aria-label="Counter value" aria-live="polite" className="my-3 block text-2xl">
        {loading ? 'Loading…' : value ?? 'Unavailable'}
      </output>
      <div className="flex gap-3">
        <button
          type="button"
          disabled={loading || busy || value === null}
          onClick={() => run(adapter.increment)}
          className="rounded border px-4 py-2 disabled:opacity-50"
        >
          Increment counter
        </button>
        <button
          type="button"
          disabled={loading || busy || value === null}
          onClick={() => run(adapter.reset)}
          className="rounded border px-4 py-2 disabled:opacity-50"
        >
          Reset counter
        </button>
      </div>
      {error && (
        <div role="alert" className="mt-3">
          <p>{error}</p>
          <button type="button" disabled={busy} onClick={() => run(adapter.read)}>
            Read current counter
          </button>
        </div>
      )}
    </aside>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { NotesPanel } from '@lantern-lab/ui';
import { nativeCounter, nativeNotes } from './native';
import { CounterPanel } from './counter';
import './styles.css';

// The compile-time branch is removed from ordinary renderer artifacts.
if (import.meta.env.MODE === 'e2e') await import('@wdio/tauri-plugin');
const root = document.getElementById('root');
if (!root) {
  document.body.textContent = 'The application could not initialize.';
} else
  createRoot(root).render(
    <StrictMode>
      <main className="p-6">
        <NotesPanel
          adapter={nativeNotes}
          storage="Offline sample: notes are kept in memory until this window closes. JSON exports use the save destination you choose."
        />
        <CounterPanel adapter={nativeCounter} />
      </main>
    </StrictMode>,
  );

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod errors_generated;
mod telemetry;
use errors_generated::{AppError, ErrorCode, PublicError};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    path::Path,
    sync::Mutex,
    time::{SystemTime, UNIX_EPOCH},
};
use tauri::{AppHandle, State};
use tauri_plugin_dialog::DialogExt;
use telemetry::{NativeOperation, Operation, TraceCarrier};
use uuid::Uuid;

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
struct Note {
    id: String,
    text: String,
    created_at: u64,
}
#[derive(Default)]
struct Notes(Mutex<Vec<Note>>);

#[derive(Default)]
struct Counter(Mutex<u32>);
impl Counter {
    fn value(&self) -> Result<u32, AppError> {
        Ok(*self.0.lock().map_err(|_| AppError::new(ErrorCode::StateUnavailable))?)
    }
    fn increment(&self) -> Result<u32, AppError> {
        let mut value = self.0.lock().map_err(|_| AppError::new(ErrorCode::StateUnavailable))?;
        let next = value.checked_add(1).ok_or_else(|| AppError::new(ErrorCode::CounterLimit))?;
        *value = next;
        Ok(next)
    }
    fn reset(&self) -> Result<u32, AppError> {
        let mut value = self.0.lock().map_err(|_| AppError::new(ErrorCode::StateUnavailable))?;
        *value = 0;
        Ok(*value)
    }
}


fn new_note(text: &str) -> Result<Note, AppError> {
    // Match the portable contract's ECMAScript TrimString whitespace set.
    // Rust's Unicode White_Space removes U+0085 but preserves U+FEFF.
    let text = text.trim_matches(|character| {
        matches!(
            character,
            '\u{0009}'..='\u{000d}'
                | '\u{0020}'
                | '\u{00a0}'
                | '\u{1680}'
                | '\u{2000}'..='\u{200a}'
                | '\u{2028}'
                | '\u{2029}'
                | '\u{202f}'
                | '\u{205f}'
                | '\u{3000}'
                | '\u{feff}'
        )
    });
    if text.is_empty() || text.encode_utf16().count() > 1000 {
        return Err(AppError::new(ErrorCode::InputInvalid));
    }
    let millis = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| AppError::new(ErrorCode::ClockInvalid))?
        .as_millis();
    Ok(Note {
        id: Uuid::new_v4().to_string(),
        text: text.to_owned(),
        created_at: u64::try_from(millis).map_err(|_| AppError::new(ErrorCode::ClockInvalid))?,
    })
}

fn read_notes(state: State<'_, Notes>) -> Result<Vec<Note>, AppError> {
    Ok(state
        .0
        .lock()
        .map_err(|_| AppError::new(ErrorCode::StateUnavailable))?
        .clone())
}
fn insert_note(text: String, state: State<'_, Notes>) -> Result<Note, AppError> {
    let note = new_note(&text)?;
    state
        .0
        .lock()
        .map_err(|_| AppError::new(ErrorCode::StateUnavailable))?
        .push(note.clone());
    Ok(note)
}
fn remove_note(id: String, state: State<'_, Notes>) -> Result<(), AppError> {
    Uuid::parse_str(&id).map_err(|_| AppError::new(ErrorCode::InputInvalid))?;
    let mut notes = state
        .0
        .lock()
        .map_err(|_| AppError::new(ErrorCode::StateUnavailable))?;
    let previous = notes.len();
    notes.retain(|note| note.id != id);
    if notes.len() == previous {
        return Err(AppError::new(ErrorCode::ResourceMissing));
    }
    Ok(())
}

fn write_notes(path: &Path, notes: &[Note]) -> Result<(), AppError> {
    let json =
        serde_json::to_vec_pretty(notes).map_err(|_| AppError::new(ErrorCode::ExportFailed))?;
    fs::write(path, json).map_err(|_| AppError::new(ErrorCode::ExportFailed))
}

fn selected_destination(app: &AppHandle) -> Result<Option<std::path::PathBuf>, AppError> {
    #[cfg(feature = "e2e")]
    if let Some(path) = std::env::var_os("STARTER_TEST_SAVE_PATH") {
        return if path == "cancel" {
            Ok(None)
        } else {
            Ok(Some(path.into()))
        };
    }
    app.dialog()
        .file()
        .add_filter("JSON", &["json"])
        .set_file_name("notes.json")
        .blocking_save_file()
        .map(|file| {
            file.into_path()
                .map_err(|_| AppError::new(ErrorCode::ExportFailed))
        })
        .transpose()
}

async fn save_notes(app: AppHandle, state: State<'_, Notes>) -> Result<Option<String>, AppError> {
    let notes = state
        .0
        .lock()
        .map_err(|_| AppError::new(ErrorCode::StateUnavailable))?
        .clone();
    tauri::async_runtime::spawn_blocking(move || {
        let Some(path) = selected_destination(&app)? else {
            return Ok(None);
        };
        write_notes(&path, &notes)?;
        Ok(Some(path.to_string_lossy().into_owned()))
    })
    .await
    .map_err(|_| AppError::new(ErrorCode::ExportFailed))?
}

fn project<T>(operation: Operation, result: Result<T, AppError>) -> Result<T, PublicError> {
    operation.record(&result);
    result.map_err(|error| error.public())
}
#[tauri::command]
fn list_notes(
    state: State<'_, Notes>,
    telemetry: Option<TraceCarrier>,
) -> Result<Vec<Note>, PublicError> {
    let operation = Operation::new(NativeOperation::List, telemetry);
    project(operation, read_notes(state))
}
#[tauri::command]
fn add_note(
    text: String,
    state: State<'_, Notes>,
    telemetry: Option<TraceCarrier>,
) -> Result<Note, PublicError> {
    let operation = Operation::new(NativeOperation::Add, telemetry);
    project(operation, insert_note(text, state))
}
#[tauri::command]
fn delete_note(
    id: String,
    state: State<'_, Notes>,
    telemetry: Option<TraceCarrier>,
) -> Result<(), PublicError> {
    let operation = Operation::new(NativeOperation::Remove, telemetry);
    project(operation, remove_note(id, state))
}
#[tauri::command]
async fn export_notes(
    app: AppHandle,
    state: State<'_, Notes>,
    telemetry: Option<TraceCarrier>,
) -> Result<Option<String>, PublicError> {
    let operation = Operation::new(NativeOperation::Export, telemetry);
    project(operation, save_notes(app, state).await)
}

#[tauri::command]
fn read_counter(state: State<'_, Counter>, telemetry: Option<TraceCarrier>) -> Result<u32, PublicError> {
    project(Operation::new(NativeOperation::CounterRead, telemetry), state.value())
}
#[tauri::command]
fn increment_counter(state: State<'_, Counter>, telemetry: Option<TraceCarrier>) -> Result<u32, PublicError> {
    project(Operation::new(NativeOperation::CounterIncrement, telemetry), state.increment())
}
#[tauri::command]
fn reset_counter(state: State<'_, Counter>, telemetry: Option<TraceCarrier>) -> Result<u32, PublicError> {
    project(Operation::new(NativeOperation::CounterReset, telemetry), state.reset())
}

