import { createElement } from 'react';
import { cleanup, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { Ok, Err, failure, publicFailure, type Result, type PublicError } from '@lantern-lab/contracts';
import { CounterPanel, type CounterAdapter } from '../src/counter';

afterEach(cleanup);
const adapter = (): CounterAdapter => ({
  read: vi.fn<CounterAdapter['read']>().mockResolvedValue(Ok(7)),
  increment: vi.fn<CounterAdapter['increment']>().mockResolvedValue(Ok(8)),
  reset: vi.fn<CounterAdapter['reset']>().mockResolvedValue(Ok(0)),
});
describe('native counter UI', () => {
  it('loads the native value, increments, resets, and preserves the value after failure', async () => {
    const actions = adapter();
    render(createElement(CounterPanel, { adapter: actions }));
    const increment = screen.getByRole<HTMLButtonElement>('button', { name: 'Increment counter' });
    expect(increment.disabled).toBe(true);
    await waitFor(() => expect(screen.getByLabelText('Counter value').textContent).toBe('7'));
    const user = userEvent.setup();
    await user.click(increment);
    await waitFor(() => expect(screen.getByLabelText('Counter value').textContent).toBe('8'));
    const problem = publicFailure(failure('counter_limit'));
    vi.mocked(actions.increment).mockResolvedValueOnce(Err(problem));
    await user.click(increment);
    await screen.findByText(problem.message);
    expect(screen.getByLabelText('Counter value').textContent).toBe('8');
    vi.mocked(actions.read).mockResolvedValueOnce(Ok(8));
    await user.click(screen.getByRole('button', { name: 'Read current counter' }));
    await waitFor(() => expect(screen.queryByRole('alert')).toBeNull());
    await user.click(screen.getByRole('button', { name: 'Reset counter' }));
    await waitFor(() => expect(screen.getByLabelText('Counter value').textContent).toBe('0'));
    expect(actions.reset).toHaveBeenCalledTimes(1);
  });
  it('blocks overlapping UI mutations and retries a failed initial native read', async () => {
    const actions = adapter();
    vi.mocked(actions.read).mockResolvedValueOnce(Err(publicFailure(failure('ipc_failed'))));
    render(createElement(CounterPanel, { adapter: actions }));
    await screen.findByRole('alert');
    const increment = screen.getByRole<HTMLButtonElement>('button', { name: 'Increment counter' });
    expect(increment.disabled).toBe(true);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: 'Read current counter' }));
    await waitFor(() => expect(increment.disabled).toBe(false));
    let complete: ((result: Result<number, PublicError>) => void) | undefined;
    vi.mocked(actions.increment).mockImplementationOnce(() => new Promise(resolve => { complete = resolve; }));
    await user.click(increment);
    expect(increment.disabled).toBe(true);
    await user.click(increment);
    expect(actions.increment).toHaveBeenCalledTimes(1);
    if (!complete) throw new Error('Counter mutation did not start');
    complete(Ok(8));
    await waitFor(() => expect(increment.disabled).toBe(false));
    expect(screen.getByLabelText('Counter value').textContent).toBe('8');
  });
});

import { browser, expect } from '@wdio/globals';
import '@wdio/tauri-service';
import { readFile } from 'node:fs/promises';
import { counterValueSchema, noteSchema, notesSchema, decodePublicError } from '@lantern-lab/contracts';

async function reloadNativeWindow() {
  // The embedded driver's refresh returns before WebKit replaces the document.
  // Wait for the new document/plugin before the service's next Rust focus query.
  const marker = crypto.randomUUID();
  await browser.execute((value: string) => {
    document.documentElement.dataset.nativeReload = value;
  }, marker);
  await browser.refresh();
  // Yield to WebKit's queued unload before creating an eval completion callback.
  await browser.pause(100);
  await browser.waitUntil(
    () =>
      browser.execute(
        (value: string) =>
          document.documentElement.dataset.nativeReload !== value &&
          document.readyState === 'complete' &&
          typeof window.wdioTauri?.waitForInit === 'function' &&
          typeof window.__wdio_original_core__?.invoke === 'function',
        marker,
      ),
    { timeout: 5000, interval: 100, timeoutMsg: 'Reloaded native plugin did not initialize' },
  );
  await browser.execute(async () => {
    await window.wdioTauri?.waitForInit();
  });
}

describe('real native Tauri window and Rust IPC', () => {
  it('keeps the counter in real Rust state across renderer reload and concurrent IPC', async () => {
    await browser.tauri.execute((tauri) => tauri.core.invoke('reset_counter'));
    await reloadNativeWindow();
    await expect(browser.$('output[aria-label="Counter value"]')).toHaveText('0');
    await browser.$('button=Increment counter').click();
    await expect(browser.$('output[aria-label="Counter value"]')).toHaveText('1');
    expect(await browser.tauri.execute((tauri) => tauri.core.invoke('read_counter'))).toBe(1);
    const values = await browser.tauri.execute(async (tauri) =>
      Promise.all(Array.from({ length: 16 }, () => tauri.core.invoke('increment_counter'))),
    );
    expect(values.map(value => counterValueSchema.parse(value)).sort((left, right) => left - right)).toEqual(Array.from({ length: 16 }, (_, index) => index + 2));
    await reloadNativeWindow();
    await expect(browser.$('output[aria-label="Counter value"]')).toHaveText('17');
    await browser.$('button=Reset counter').click();
    await expect(browser.$('output[aria-label="Counter value"]')).toHaveText('0');
    expect(await browser.tauri.execute((tauri) => tauri.core.invoke('read_counter'))).toBe(0);
    await expect(browser.$('h1')).toHaveText('Notes');
  });
  it('renders offline UI and validates real CRUD/export permissions', async () => {
    await expect(browser.$('h1')).toHaveText('Notes');
    for (const text of [
      '\uFEFFnative\uFEFF',
      '\u0085',
      '\uFEFF\u0085note\u0085\uFEFF',
      `\uFEFF${'x'.repeat(1000)}\uFEFF`,
      `\uFEFF${'😀'.repeat(500)}\uFEFF`,
    ]) {
      const normalized = noteSchema.parse(
        await browser.tauri.execute(
          (tauri, value: string) => tauri.core.invoke('add_note', { text: value }),
          text,
        ),
      );
      expect(normalized.text).toBe(text.trim());
      await browser.tauri.execute(
        (tauri, id: string) => tauri.core.invoke('delete_note', { id }),
        normalized.id,
      );
    }
    await expect(
      browser.tauri.execute((tauri) => tauri.core.invoke('add_note', { text: '\uFEFF' })),
    ).rejects.toThrow();
    for (const text of ['😀'.repeat(501), `${'😀'.repeat(500)}x`]) {
      await expect(
        browser.tauri.execute(
          (tauri, value: string) => tauri.core.invoke('add_note', { text: value }),
          text,
        ),
      ).rejects.toThrow();
    }
    // Inspect the actual Rust-to-renderer rejection before the WebDriver transport wraps it.
    const publicFailure = decodePublicError(
      await browser.tauri.execute(async (tauri) => {
        try {
          await tauri.core.invoke('add_note', { text: '' });
          return null;
        } catch (error) {
          return error;
        }
      }),
    );
    expect(publicFailure.ok).toBe(true);
    if (!publicFailure.ok)
      throw new Error('Native rejection violated the generated public error policy');
    expect(publicFailure.value.code).toBe('invalid_input');
    expect(publicFailure.value.failureClass).toBe('validation');
    expect(publicFailure.value.retry).toBe('never');
    expect(publicFailure.value.diagnosticId).toMatch(/^[a-f0-9]{32}$/u);
    const note = noteSchema.parse(
      await browser.tauri.execute((tauri) =>
        tauri.core.invoke('add_note', { text: 'Native note' }),
      ),
    );
    await reloadNativeWindow();
    await expect(browser.$(`button[aria-label="Delete Native note"]`)).toExist();
    const mode = process.env.STARTER_EXPORT_CASE ?? 'save';
    if (mode === 'error') {
      await expect(
        browser.tauri.execute((tauri) => tauri.core.invoke('export_notes')),
      ).rejects.toThrow();
    } else {
      const result = await browser.tauri.execute((tauri) => tauri.core.invoke('export_notes'));
      if (mode === 'cancel') expect(result).toBeNull();
      else {
        expect(typeof result).toBe('string');
        const filename = process.env.STARTER_TEST_SAVE_PATH;
        if (!filename) throw new Error('Native export path missing');
        expect(notesSchema.parse(JSON.parse(await readFile(filename, 'utf8')))).toContainEqual(
          note,
        );
      }
    }
    await expect(
      browser.tauri.execute((tauri) => tauri.core.invoke('read_file', { path: '/unrelated' })),
    ).rejects.toThrow();
    await browser.tauri.execute(
      (tauri, id: string) => tauri.core.invoke('delete_note', { id }),
      note.id,
    );
    await reloadNativeWindow();
    await expect(browser.$('section')).toHaveText(expect.stringContaining('No notes yet.'));
  });
});
